def num_islands(grid):
    if not grid:
        return 0
    rows, cols, seen, count = len(grid), len(grid[0]), set(), 0
    for r0 in range(rows):
        for c0 in range(cols):
            if grid[r0][c0] == '1' and (r0, c0) not in seen:
                count += 1
                stack = [(r0, c0)]
                seen.add((r0, c0))
                while stack:
                    r, c = stack.pop()
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '1' and (nr, nc) not in seen:
                            seen.add((nr, nc))
                            stack.append((nr, nc))
    return count

from collections import deque

def shortest_path(grid):
    n, m = len(grid), len(grid[0])
    if grid[0][0] or grid[n - 1][m - 1]:
        return -1
    q, seen = deque([(0, 0, 1)]), {(0, 0)}
    while q:
        r, c, d = q.popleft()
        if (r, c) == (n - 1, m - 1):
            return d
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and not grid[nr][nc] and (nr, nc) not in seen:
                seen.add((nr, nc))
                q.append((nr, nc, d + 1))
    return -1

from collections import deque

def can_finish(n, prerequisites):
    indeg, nxt = [0] * n, [[] for _ in range(n)]
    for a, b in prerequisites:
        nxt[b].append(a)
        indeg[a] += 1
    q, done = deque(i for i in range(n) if indeg[i] == 0), 0
    while q:
        u = q.popleft()
        done += 1
        for v in nxt[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    return done == n

